const reg = $("Read Trigger Registry").all();
const res = $input.all();
const mult = $("Config").first().json.hungMultiplier || 1.5;
const now = Date.now();
const valid = [];
for (const r of reg) { if (r.json && r.json.workflow_id) valid.push(r.json); }
if (valid.length === 0) {
  return [{ json: { finding_type: "REGISTRY_EMPTY", severity: "MEDIUM", workflow_id: "", workflow_name: "instance", check: "1-silent-trigger", detail: "sentinel_trigger_registry is empty, so this check watched nothing. Seed it with the workflows that matter or this branch is decorative." } }];
}
const out = [];
for (let i = 0; i < valid.length; i++) {
  const r = valid[i];
  const outcome = String(r.expected_outcome || "success").toLowerCase();
  const resp = res[i] ? res[i].json : null;
  if (!resp || resp.error || !Array.isArray(resp.data)) {
    out.push({ json: { finding_type: "CHECK_BLIND", severity: "CRITICAL", workflow_id: r.workflow_id, workflow_name: r.workflow_name, check: "1-silent-trigger", detail: "could not read executions for " + r.workflow_name + ": " + (resp && resp.error ? (resp.error.message || "API error") : "no response from the n8n API") } });
    continue;
  }
  const arr = resp.data;
  const last = arr.length && arr[0].startedAt ? arr[0].startedAt : null;
  const expected = Number(r.expected_interval_minutes) || 15;
  if (outcome === "on_demand") { continue; }
  if (outcome === "failure") {
    if (last) {
      const mins = Math.round((now - new Date(last).getTime()) / 60000);
      out.push({ json: { finding_type: "UNEXPECTED_SUCCESS", severity: "MEDIUM", workflow_id: r.workflow_id, workflow_name: r.workflow_name, owner: r.owner, check: "1-silent-trigger", detail: r.workflow_name + " is registered as designed to fail, but it succeeded " + mins + " minutes ago. A test that stops failing has stopped testing anything." } });
    }
    continue;
  }
  if (!last) {
    out.push({ json: { finding_type: "SILENT_TRIGGER", severity: "CRITICAL", workflow_id: r.workflow_id, workflow_name: r.workflow_name, owner: r.owner, check: "1-silent-trigger", detail: "no successful execution on record, expected every " + expected + " minutes" } });
    continue;
  }
  const elapsed = Math.round((now - new Date(last).getTime()) / 60000);
  if (elapsed > expected * mult) {
    out.push({ json: { finding_type: "SILENT_TRIGGER", severity: "CRITICAL", workflow_id: r.workflow_id, workflow_name: r.workflow_name, owner: r.owner, check: "1-silent-trigger", detail: "no successful execution in " + elapsed + " minutes, expected every " + expected } });
  }
}
return out;

