  if (!s.errorWorkflow && !isErrorHandler) out.push({ json: { finding_type: "DOD_NO_ERROR_WORKFLOW", severity: "HIGH", workflow_id: w.id, workflow_name: w.name, check: "5-dod-lint", detail: label + " has no error workflow configured" } });
  if (!s.executionTimeout || Number(s.executionTimeout) < 1) out.push({ json: { finding_type: "DOD_NO_TIMEOUT", severity: "HIGH", workflow_id: w.id, workflow_name: w.name, check: "5-dod-lint", detail: label + " has no execution timeout set" } });
  let hasOwner = false;
