  if (!hasOwner) out.push({ json: { finding_type: "DOD_NO_OWNER", severity: "MEDIUM", workflow_id: w.id, workflow_name: w.name, check: "5-dod-lint", detail: label + " has no owner: tag" } });
  if (!monitored[w.id]) out.push({ json: { finding_type: "DOD_NOT_MONITORED", severity: "MEDIUM", workflow_id: w.id, workflow_name: w.name, check: "5-dod-lint", detail: label + " is active but not in sentinel_trigger_registry" } });
}
