const pages = $input.all();
const wfs = [];
let good = 0;
let firstErr = "";
for (const p of pages) {
  const j = p && p.json ? p.json : null;
  if (!j || j.error || !Array.isArray(j.data)) {
    if (!firstErr) firstErr = j && j.error ? (j.error.message || "API error") : "no response from the n8n API";
    continue;
  }
  good++;
  for (const w of j.data) wfs.push(w);
}
if (good === 0) {
  return [{ json: { finding_type: "CHECK_BLIND", severity: "CRITICAL", workflow_id: "", workflow_name: "instance", check: "6-credential-map", detail: "could not list workflows: " + firstErr + ". The credential map was NOT built this run." } }];
}
const index = {};
const out = [];
const needsCred = ["httpRequest", "slack", "gmail", "postgres", "mysql", "notion", "airtable", "googleSheets", "openAi", "telegram", "discord", "hubspot", "jira", "stripe"];
for (const w of wfs) {
  const nodes = Array.isArray(w.nodes) ? w.nodes : [];
  const live = w.active === true && w.isArchived !== true;
  for (const n of nodes) {
    const creds = n.credentials || {};
