const items = $input.all();
const CHECKS = ["1-silent-trigger", "2-hung-executions", "3-error-spike", "4-retention", "5-dod-lint", "6-credential-map", "7-vendor-probes"];
const ran = {};
try { $("Detect Silent Triggers").all(); ran["1-silent-trigger"] = true; } catch (e) { }
try { $("Detect Hung Executions").all(); ran["2-hung-executions"] = true; } catch (e) { }
try { $("Detect Error Spikes").all(); ran["3-error-spike"] = true; } catch (e) { }
try { $("Detect Retention Breach").all(); ran["4-retention"] = true; } catch (e) { }
try { $("Lint Definition Of Done").all(); ran["5-dod-lint"] = true; } catch (e) { }
try { $("Map Credential Usage").all(); ran["6-credential-map"] = true; } catch (e) { }
try { $("Compare Probe Status").all(); ran["7-vendor-probes"] = true; } catch (e) { }
const owners = {};
try {
  const reg = $("Read Trigger Registry").all();
  for (const r of reg) { if (r.json && r.json.workflow_id) owners[r.json.workflow_id] = r.json.owner; }
} catch (e) { }
const nowIso = new Date().toISOString();
const day = nowIso.slice(0, 10);
const findings = [];
const blind = {};
for (const it of items) {
  const f = it.json || {};
  if (!f.finding_type) continue;
  if (f.finding_type === "CHECK_BLIND" && f.check) blind[f.check] = true;
  const wid = f.workflow_id === undefined || f.workflow_id === null ? "" : String(f.workflow_id);
  const suffix = f.check ? ":" + f.check : "";
  const key = f.finding_type === "CREDENTIAL_INDEX" ? "CREDENTIAL_INDEX:" + day : f.finding_type + ":" + wid + suffix + ":" + day;
  findings.push({ json: {
    finding_key: key,
    finding_type: String(f.finding_type),
    severity: String(f.severity || "MEDIUM"),
    workflow_id: wid,
    workflow_name: String(f.workflow_name || wid || "instance"),
    detail: String(f.detail || ""),
    detected_at: nowIso,
    owner: String(f.owner || owners[wid] || "unassigned")
  } });
}
for (const c of CHECKS) {
  if (!ran[c]) {
    blind[c] = true;
    findings.push({ json: { finding_key: "CHECK_SILENT:" + c + ":" + day, finding_type: "CHECK_SILENT", severity: "CRITICAL", workflow_id: "", workflow_name: c, detail: "check " + c + " never executed this run - it was skipped, not clean. A branch that does not run cannot be trusted to say all clear.", detected_at: nowIso, owner: "platform" } });
  }
