const blindCount = blindList.length;
const checksOk = CHECKS.length - blindCount;
const bySev = {};
const byType = {};
for (const f of findings) {
  if (f.json.severity === "INFO") continue;
  bySev[f.json.severity] = (bySev[f.json.severity] || 0) + 1;
  byType[f.json.finding_type] = (byType[f.json.finding_type] || 0) + 1;
}
let status = bySev.CRITICAL ? "RED" : (bySev.HIGH ? "AMBER" : "GREEN");
if (blindCount > 0 && status === "GREEN") status = "AMBER";
const real = [];
for (const f of findings) { if (f.json.severity !== "INFO") real.push(f); }
const order = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };
real.sort(function (a, b) { return (order[a.json.severity] === undefined ? 9 : order[a.json.severity]) - (order[b.json.severity] === undefined ? 9 : order[b.json.severity]); });
const top = real.slice(0, 10);
const lines = [];
