  prefix = "";
} else if (changed && status === "GREEN") {
  prefix = "RECOVERED - was " + last + ", now GREEN.\n\n";
} else if (changed) {
  prefix = "CHANGED - was " + last + ".\n\n";
} else if (digestDue) {
  prefix = "STILL " + status + " after " + Math.round(hoursSinceAlert) + "h. Nothing new since the last message; this is the daily reminder so silence keeps meaning unchanged rather than unwatched.\n\n";
}
return [{ json: {
  should_alert: shouldAlert,
  transition: changed ? (last + " -> " + status) : "none",
  status: status,
  alert_text: prefix + String(summary.alert_text || ("Platform Sentinel: " + status)),
  state_key: "platform",
  last_status: status,
  changed_at: changed ? nowIso : String(prev.changed_at || nowIso),
  last_alert_at: shouldAlert ? nowIso : String(prev.last_alert_at || "")
} }];
